// FindMany retrieves multiple Ingredient records matching the filter, and how
// many it matches in all, -1 when the options skip the count
func (r *IngredientRepository) FindMany(ctx context.Context, filter *IngredientFilter, opts *IngredientFindOptions) ([]*types.Ingredient, int, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, 0, fmt.Errorf("fields must be specified in FindOptions for performance")
	}

	// Build selected fields in OrderedMembers order so FK columns match scan order.
	fieldStrings := ingredientFieldStrings(opts.Fields)

	// Validate fields
	if err := validateFields(fieldStrings, IngredientAllowedFields); err != nil {
		return nil, 0, err
	}

	// Build SELECT clause
	selectFields := buildSelectFieldsTyped(fieldStrings, "ingredient")
	if selectFields == "" {
		return nil, 0, fmt.Errorf("no valid fields specified")
	}

	// Build WHERE clause
	var args []interface{}
	whereClause := filter.buildWhereClause(&args, 0)

	// Build ORDER BY clause
	orderByClause := buildIngredientOrderByClause(opts.OrderBy, `ingredient`)

	// Build LIMIT/OFFSET clause
	limitOffsetClause := buildLimitOffsetClauseTyped(opts.Limit, opts.Offset)

	// Build query
	query := fmt.Sprintf(`SELECT %s FROM ingredient%s%s%s`, selectFields, whereClause, orderByClause, limitOffsetClause)

	// Get total count, unless the options skip it (D89)
	totalCount := -1
	if !opts.SkipCount {
		countQuery := fmt.Sprintf(`SELECT COUNT(*) FROM ingredient%s`, whereClause)

		var countRow pgx.Row
		if r.tx != nil {
			countRow = r.tx.QueryRow(ctx, countQuery, args...)
		} else {
			countRow = r.db.pool.QueryRow(ctx, countQuery, args...)
		}
		if err := countRow.Scan(&totalCount); err != nil {
			return nil, 0, fmt.Errorf("failed to get count: %w", err)
		}
	}

	results, err := r.findRows(ctx, "FindMany", query, args, fieldStrings, opts.Fields)
	if err != nil {
		return nil, 0, err
	}
	return results, totalCount, nil
}

// ingredientFieldStrings are the columns fields selects, in OrderedMembers
// order so FK columns match scan order, and the primary key when fields
// hydrates a hasMany relation, which maps the children by it.
func ingredientFieldStrings(fields IngredientFields) []string {
	var fieldStrings []string
	if fields.Id {
		fieldStrings = append(fieldStrings, "id")
	}
	if fields.Recipe || !fields.RecipeNested.IsZero() {
		fieldStrings = append(fieldStrings, "recipe_id")
	}
	if fields.StepKey {
		fieldStrings = append(fieldStrings, "step_key")
	}
	if fields.Quantity {
		fieldStrings = append(fieldStrings, "quantity")
	}
	if fields.Substitutes {
		fieldStrings = append(fieldStrings, "substitutes")
	}
	if fields.EntityKey {
		fieldStrings = append(fieldStrings, "entity_key")
	}
	if fields.Ref || !fields.RefNested.IsZero() {
		fieldStrings = append(fieldStrings, "ref_id")
	}
	if fields.DeletedOnRef {
		fieldStrings = append(fieldStrings, "deleted_on_ref")
	}
	if fields.Version {
		fieldStrings = append(fieldStrings, "_version")
	}
	return fieldStrings
}

// findRows runs query, a select of the columns fieldStrings names, in turn,
// with args, scans its rows, and hydrates the relations fields selects, as
// FindMany and FindPage read them. method names the caller in an error.
func (r *IngredientRepository) findRows(ctx context.Context, method, query string, args []interface{}, fieldStrings []string, fields IngredientFields) ([]*types.Ingredient, error) {
	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results
	results := []*types.Ingredient{}
	for rows.Next() {
		result := &types.Ingredient{}

		// Create temporary variables for nullable fields that need pointer scanning (per-row)

		var tempSubstitutes []byte

		// Create temporary variables for relationship foreign keys (we don't store these directly on the struct)
		var tempRelRecipe *types.IdentityUUID
		var tempRelRef *types.IdentityUUID

		// Track whether special fields were selected so we can post-process after Scan.

		var selectedRelRecipe bool
		var selectedRelRef bool

		scanDest := make([]any, len(fieldStrings))
		for i, fieldName := range fieldStrings {
			switch fieldName {
			case "id":
				scanDest[i] = &result.Id
			case "step_key":
				scanDest[i] = &result.StepKey
			case "quantity":
				scanDest[i] = &result.Quantity
			case "substitutes":
				scanDest[i] = &tempSubstitutes
			case "entity_key":
				scanDest[i] = &result.EntityKey
			case "deleted_on_ref":
				scanDest[i] = &result.DeletedOnRef
			case "_version":
				scanDest[i] = &result.Version
			case "recipe_id":
				scanDest[i] = &tempRelRecipe
				selectedRelRecipe = true
			case "ref_id":
				scanDest[i] = &tempRelRef
				selectedRelRef = true
			default:
				return nil, fmt.Errorf("unexpected field %q for Ingredient.%s", fieldName, method)
			}
		}

		if err := rows.Scan(scanDest...); err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present
		var jsonFieldDecodeErr error

		if len(tempSubstitutes) > 0 {
			if err := unmarshalGenericJSONFieldValue(tempSubstitutes, &result.Substitutes); err != nil {
				jsonFieldDecodeErr = fmt.Errorf("failed to decode JSON field substitutes: %w", err)
			}
		}
		if jsonFieldDecodeErr != nil {
			return nil, jsonFieldDecodeErr
		}

		// Set relationship IDs from scanned FK values (hydration happens after loop)
		if selectedRelRecipe && tempRelRecipe != nil {
			result.Recipe.Id = ingredientUUIDPtr(*tempRelRecipe)
		}
		if selectedRelRef && tempRelRef != nil {
			result.Ref.Id = ingredientUUIDPtr(*tempRelRef)
		}

		results = append(results, result)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	// Batch hydrate relationships (outside the row loop for efficiency)
	if fields.Recipe || !fields.RecipeNested.IsZero() {
		// Collect unique FK IDs from results (dedupe during collection)
		recipeIDSet := make(map[types.IdentityUUID]bool)
		var recipeIDs []types.IdentityUUID
		for _, result := range results {
			var zeroID types.IdentityUUID
			recipeID, ok := ingredientUUIDValue(result.Recipe.Id)
			if ok && recipeID != zeroID && !recipeIDSet[recipeID] {
				recipeIDSet[recipeID] = true
				recipeIDs = append(recipeIDs, recipeID)
			}
		}

		// Batch fetch related entities with typed child field options.
		childFields := (RecipeFields{}).All()
		childFieldsAreDefault := true
		if !fields.RecipeNested.IsZero() {
			childFields = fields.RecipeNested
			childFieldsAreDefault = false
		}

		recipeMap, err := r.batchRecipeByIDs(ctx, recipeIDs, &RecipeFindOptions{
			Fields: childFields,
			Limit:  len(recipeIDs),
		}, childFieldsAreDefault)
		if err != nil {
			return nil, fmt.Errorf("failed to batch fetch recipe: %w", err)
		}

		// Hydrate results from map
		for _, result := range results {
			recipeID, ok := ingredientUUIDValue(result.Recipe.Id)
			if ok {
				if rel, ok := recipeMap[recipeID]; ok {
					result.Recipe = *rel
				}
			}
		}
	}
	if fields.Ref || !fields.RefNested.IsZero() {
		// Collect unique FK IDs from results (dedupe during collection)
		refIDSet := make(map[types.IdentityUUID]bool)
		var refIDs []types.IdentityUUID
		for _, result := range results {
			var zeroID types.IdentityUUID
			refID, ok := ingredientUUIDValue(result.Ref.Id)
			if ok && refID != zeroID && !refIDSet[refID] {
				refIDSet[refID] = true
				refIDs = append(refIDs, refID)
			}
		}

		// Batch fetch related entities with typed child field options.
		childFields := (RecipeRefFields{}).All()
		childFieldsAreDefault := true
		if !fields.RefNested.IsZero() {
			childFields = fields.RefNested
			childFieldsAreDefault = false
		}

		refMap, err := r.batchRefByIDs(ctx, refIDs, &RecipeRefFindOptions{
			Fields: childFields,
			Limit:  len(refIDs),
		}, childFieldsAreDefault)
		if err != nil {
			return nil, fmt.Errorf("failed to batch fetch ref: %w", err)
		}

		// Hydrate results from map
		for _, result := range results {
			refID, ok := ingredientUUIDValue(result.Ref.Id)
			if ok {
				if rel, ok := refMap[refID]; ok {
					result.Ref = *rel
				}
			}
		}
	}

	return results, nil
}

// FindPage reads a page of the Ingredient rows filter finds (D60, amended), in
// opts.Sort's order, ties broken by id in the same direction: up to
// opts.Limit rows after opts.After, and Next when more follow. It runs one
// query of opts.Limit + 1 rows and no count. A key is a row's id alone:
// in an order by a sort field, the query reads the key's row for its value,
// soft-deleted or not and whatever the filter, so a row the filter no longer
// finds still places the page. An After that holds no id, or whose row
// no longer exists in an order by a sort field, is ErrPageKey. A key of another
// order cannot be told from one of this order: the router refuses a cursor
// of another sort before FindPage reads it.
func (r *IngredientRepository) FindPage(ctx context.Context, filter *IngredientFilter, opts *IngredientPageOptions) (*IngredientPage, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in PageOptions for performance")
	}
	if opts.Limit < 0 {
		return nil, fmt.Errorf("orm: a page of Ingredient rows holds 1 or more, not %d", opts.Limit)
	}
	limit := opts.Limit
	if limit == 0 {
		limit = 100
	}
	field := opts.Sort.Field
	if field == "" {
		field = IngredientSortById
	}
	column, ok := ingredientSortColumns[field]
	if !ok {
		return nil, fmt.Errorf("orm: Ingredient sorts by id, stepKey, quantity and entityKey, not %q", string(field))
	}
	byKey := field == IngredientSortById

	// Next is the key of the page's last row, so the page reads its primary
	// key whatever Fields selects.
	fieldStrings := ingredientFieldStrings(opts.Fields)
	if !containsString(fieldStrings, "id") {
		fieldStrings = append(fieldStrings, "id")
	}
	if err := validateFields(fieldStrings, IngredientAllowedFields); err != nil {
		return nil, err
	}
	selectFields := buildSelectFieldsTyped(fieldStrings, "ingredient")
	// The filter's conditions, each qualified by the table, then the
	// keyset's.
	var args []interface{}
	conditions := filter.conditions(&args, 0)
	comparison, direction := ">", "ASC"
	if opts.Sort.Desc {
		comparison, direction = "<", "DESC"
	}
	var key any
	if opts.After != nil {
		var err error
		if key, err = opts.After.arg(); err != nil {
			return nil, err
		}
		args = append(args, key)
		placeholder := fmt.Sprintf("$%d", len(args))
		if byKey {
			conditions = append(conditions, fmt.Sprintf(`ingredient.id %s %s`, comparison, placeholder))
		} else {
			// The key's row gives the sort field's value: no deleted_at
			// condition and no filter, so a row soft-deleted or changed
			// since the page before still places this one.
			conditions = append(conditions, fmt.Sprintf(`(%s, ingredient.id) %s ((SELECT %s FROM ingredient AS page_key WHERE page_key.id = %s), %s)`,
				column.sql, comparison, column.key, placeholder, placeholder))
		}
	}
	whereClause := ""
	if len(conditions) > 0 {
		whereClause = " WHERE " + strings.Join(conditions, " AND ")
	}
	orderByClause := fmt.Sprintf(" ORDER BY %s %s", column.sql, direction)
	if !byKey {
		orderByClause += fmt.Sprintf(`, ingredient.id %s`, direction)
	}
	query := fmt.Sprintf(`SELECT %s FROM ingredient%s%s LIMIT %d`, selectFields, whereClause, orderByClause, limit+1)

	rows, err := r.findRows(ctx, "FindPage", query, args, fieldStrings, opts.Fields)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 && opts.After != nil && !byKey {
		// A key whose row no longer exists places no row: its value is
		// null, which no row comes after. Only then is the page empty
		// without being the last.
		if err := r.pageKeyExists(ctx, key); err != nil {
			return nil, err
		}
	}
	page := &IngredientPage{Rows: rows}
	if len(rows) > limit {
		page.Rows = rows[:limit]
		page.Next = ingredientPageKeyOf(page.Rows[limit-1])
	}
	return page, nil
}

// pageKeyExists is nil when the table holds a row whose primary key is key,
// soft-deleted or not, and ErrPageKey when it holds none.
func (r *IngredientRepository) pageKeyExists(ctx context.Context, key any) error {
	query := `SELECT EXISTS (SELECT 1 FROM ingredient WHERE ingredient.id = $1)`
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, key)
	} else {
		row = r.db.pool.QueryRow(ctx, query, key)
	}
	var exists bool
	if err := row.Scan(&exists); err != nil {
		return fmt.Errorf("failed to read the page key's row: %w", err)
	}
	if !exists {
		return fmt.Errorf("%w: no Ingredient row has the key's id", ErrPageKey)
	}
	return nil
}

// CreateOne inserts a new Ingredient record
func (r *IngredientRepository) CreateOne(ctx context.Context, input *types.Ingredient) (*types.Ingredient, error) {
	// Set audit fields

	// Build INSERT query
	var fields []string
	var placeholders []string
	var values []interface{}
	paramNum := 0
	// Schema-owned identities may supply a stable UUID. A zero value keeps the
	// database-generated default used by ordinary creates.
	{
		var zeroPrimaryKey types.IdentityUUID
		if primaryKey, ok := ingredientUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
			fields = append(fields, `id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, primaryKey.ToUUID())
		}
	}
	// Required field: stepKey
	fields = append(fields, `step_key`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.StepKey.ToUUID())
	// Required field: quantity
	fields = append(fields, `quantity`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Quantity)
	// Required field: substitutes
	fields = append(fields, `substitutes`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	jsonValueSubstitutes, err := marshalJSONFieldValue(input.Substitutes)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal JSON field substitutes: %w", err)
	}
	values = append(values, jsonValueSubstitutes)
	// Auto-generated field: entityKey - only add if set
	{
		if !reflect.ValueOf(input.EntityKey).IsZero() {
			fields = append(fields, `entity_key`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.EntityKey.ToUUID())
		}
	}
	// Required field: deletedOnRef
	fields = append(fields, `deleted_on_ref`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.DeletedOnRef)

	// Handle relationship foreign key columns
	// Relationship: recipe (FK: recipe_id)
	{
		var zeroId types.IdentityUUID
		if relID, ok := ingredientUUIDValue(input.Recipe.Id); ok && relID != zeroId {
			fields = append(fields, `recipe_id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, relID.ToUUID())
		}
	}
	// Relationship: ref (FK: ref_id)
	{
		var zeroId types.IdentityUUID
		if relID, ok := ingredientUUIDValue(input.Ref.Id); ok && relID != zeroId {
			fields = append(fields, `ref_id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, relID.ToUUID())
		}
	}

	// Build RETURNING clause with explicit column order matching scan order (using OrderedMembers for schema order)
	returningClause := `"id", "recipe_id", "step_key", "quantity", "substitutes", "entity_key", "ref_id", "deleted_on_ref", "_version"`
	query := fmt.Sprintf(
		`INSERT INTO ingredient (%s) VALUES (%s) RETURNING %s`,
		strings.Join(fields, ", "),
		strings.Join(placeholders, ", "),
		returningClause,
	)

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}

	// Scan result
	result := &types.Ingredient{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempSubstitutes []byte

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)
	var tempRelRecipe *types.IdentityUUID
	var tempRelRef *types.IdentityUUID

	// Scan all fields in schema order (matches DDL column order)
	if err := row.Scan(

		&result.Id,

		&tempRelRecipe,

		&result.StepKey,

		&result.Quantity,

		&tempSubstitutes,

		&result.EntityKey,

		&tempRelRef,

		&result.DeletedOnRef,

		&result.Version,
	); err != nil {
		return nil, fmt.Errorf("failed to scan result: %w", err)
	}

	// Copy nullable fields when present

	if len(tempSubstitutes) > 0 {
		if err := unmarshalGenericJSONFieldValue(tempSubstitutes, &result.Substitutes); err != nil {
			return nil, fmt.Errorf("failed to decode JSON field substitutes: %w", err)
		}
	}

	// Set relationship IDs from scanned FK values
	if tempRelRecipe != nil {
		result.Recipe.Id = ingredientUUIDPtr(*tempRelRecipe)
	}
	if tempRelRef != nil {
		result.Ref.Id = ingredientUUIDPtr(*tempRelRef)
	}

	return result, nil
}

// ingredientUniqueKeys are the conflict targets of Ingredient's unique keys, and
// the assignment an upsert that sets nothing writes, so the row it
// conflicts with is returned (sqlutil.UniqueKey, D79); the read of the rows
// that hold keys, which an upsert only if changed reads back, empty for a
// key over an expression, and the key's columns as a batch insert's cells
// name them (D89).
var ingredientUniqueKeys = map[IngredientUniqueKey]struct {
	conflict, keep, rows string
	columns              []string
}{
	IngredientUniqueById:           {`(id)`, `id = EXCLUDED.id`, `SELECT "id", "recipe_id", "step_key", "quantity", "substitutes", "entity_key", "ref_id", "deleted_on_ref", "_version" FROM ingredient WHERE (id) IN (%s)`, []string{`id`}},
	IngredientUniqueByEntityKeyRef: {`(entity_key, ref_id)`, `entity_key = EXCLUDED.entity_key`, `SELECT "id", "recipe_id", "step_key", "quantity", "substitutes", "entity_key", "ref_id", "deleted_on_ref", "_version" FROM ingredient WHERE (entity_key, ref_id) IN (%s)`, []string{`entity_key`, `ref_id`}},
}

// ingredientKeyOf is the text of row's values of the unique key on, as
// UpsertMany matches the rows a statement returns to its inputs, or false
// when the insert leaves one of them to the database (D89).
func ingredientKeyOf(on IngredientUniqueKey, row *types.Ingredient) (string, bool) {
	switch on {
	case IngredientUniqueById:
		return upsertKeyText(upsertKeyValue(row.Id, false))
	case IngredientUniqueByEntityKeyRef:
		return upsertKeyText(upsertKeyValue(row.EntityKey, false), upsertKeyValue(row.Ref.Id, false))
	}
	return "", false
}

// database is the Database the repository runs on.
func (r *IngredientRepository) database() *Database {
	if r.txDB != nil {
		return r.txDB
	}
	return r.db
}

// scanReturned scans a row of every column of Ingredient, as a write returns
// it, and, with inserted, the flag an upsert returns after them (D89).
func (r *IngredientRepository) scanReturned(row pgx.Row, inserted *bool) (*types.Ingredient, error) {
	result := &types.Ingredient{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempSubstitutes []byte

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)
	var tempRelRecipe *types.IdentityUUID
	var tempRelRef *types.IdentityUUID

	// Scan all fields in schema order (matches DDL column order)
	dest := []any{

		&result.Id,

		&tempRelRecipe,

		&result.StepKey,

		&result.Quantity,

		&tempSubstitutes,

		&result.EntityKey,

		&tempRelRef,

		&result.DeletedOnRef,

		&result.Version,
	}
	if inserted != nil {
		dest = append(dest, inserted)
	}
	if err := row.Scan(dest...); err != nil {
		return nil, err
	}

	// Copy nullable fields when present

	if len(tempSubstitutes) > 0 {
		if err := unmarshalGenericJSONFieldValue(tempSubstitutes, &result.Substitutes); err != nil {
			return nil, fmt.Errorf("failed to decode JSON field substitutes: %w", err)
		}
	}

	// Set relationship IDs from scanned FK values
	if tempRelRecipe != nil {
		result.Recipe.Id = ingredientUUIDPtr(*tempRelRecipe)
	}
	if tempRelRef != nil {
		result.Ref.Id = ingredientUUIDPtr(*tempRelRef)
	}

	return result, nil
}

// UpsertOne inserts input, or, when a row already holds its value of the
// unique key on, applies update to that row instead, and returns the row
// (D79). The insert writes what CreateOne writes and the update what
// UpdateOne writes, updated_at and updated_by among it, but an update that
// sets no field leaves the row as it is.
func (r *IngredientRepository) UpsertOne(ctx context.Context, input *types.Ingredient, on IngredientUniqueKey, update *IngredientUpdate) (*types.Ingredient, error) {
	result, err := r.UpsertOneResult(ctx, input, on, update, nil)
	if err != nil {
		return nil, err
	}
	return result.Row, nil
}

// UpsertOneResult is UpsertOne, and what it did with the row: inserted it,
// updated the row that held the key, or left that row as it was (D89).
// With opts.OnlyIfChanged it updates the row only when a field the update
// sets differs from what the row holds, which it reads back otherwise. A write that
// may take more than one statement runs in a transaction of its own when
// none is open.
func (r *IngredientRepository) UpsertOneResult(ctx context.Context, input *types.Ingredient, on IngredientUniqueKey, update *IngredientUpdate, opts *UpsertOptions) (UpsertResult[*types.Ingredient], error) {
	var none UpsertResult[*types.Ingredient]
	key, ok := ingredientUniqueKeys[on]
	if !ok {
		return none, fmt.Errorf("orm: Ingredient has no unique key %q", string(on))
	}
	if opts == nil {
		opts = &UpsertOptions{}
	}
	if opts.OnlyIfChanged && key.rows == "" {
		return none, upsertExpressionKey("UpsertOneResult", "Ingredient", string(on))
	}
	if update == nil {
		update = &IngredientUpdate{}
	}
	write := func(repo *IngredientRepository) (UpsertResult[*types.Ingredient], error) {
		result, err := repo.upsertRow(ctx, input, on, update, opts.OnlyIfChanged)
		if err != nil {
			return none, err
		}
		return *result, nil
	}
	if !opts.OnlyIfChanged {
		return write(r)
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (UpsertResult[*types.Ingredient], error) {
		return write(&IngredientRepository{tx: tx, txDB: r.database()})
	})
}

// upsertRow is UpsertOneResult on the repository's connection: the upsert,
// a read of the row it left as it was, only if changed, and the second
