		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`entity_key = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `ingredient.entity_key`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
